<?php
// ===============================================
// ARQUIVO: 5c_escalas/lib/ajuda.php
// Central de Ajuda: glossário, FAQ, passos do tour e "Ações necessárias".
// O conteúdo longo fica aqui nos dois idiomas (pt e en), escolhido por escIdioma().
// Ao publicar uma versão oficial, revisar o que mudou aqui (gatilho de publicação).
// ===============================================

function escAjudaTexto(array $item, string $campo): string {
    return (string) ($item[$campo . (escEmIngles() ? '_en' : '')] ?? $item[$campo] ?? '');
}

// Glossário: termo, definição (pt / en) e tela relacionada.
function escGlossario(): array {
    return [
        ['termo' => 'Unidade', 'termo_en' => 'Unit', 'def' => 'Um dos 3 grupos da operação (U1, U2, U3). Cada unidade tem os 3 turnos e 3 núcleos por turno.', 'def_en' => 'One of the 3 operation groups (U1, U2, U3). Each unit has the 3 shifts and 3 cores per shift.', 'tela' => 'organograma'],
        ['termo' => 'Turno', 'termo_en' => 'Shift', 'def' => 'A (05–13, blocos T2 e T3), C (13–21, T4 e T5) e D (21–05, T6 e o T1 do dia seguinte). Cada pessoa fica num turno só.', 'def_en' => 'A (05–13, blocks T2 and T3), C (13–21, T4 and T5) and D (21–05, T6 and the next day\'s T1). Each person stays in one shift.', 'tela' => 'grade'],
        ['termo' => 'Bloco (T1 a T6)', 'termo_en' => 'Block (T1 to T6)', 'def' => 'Faixa de 4 horas da escala no site da 5C. Um turno tem 2 blocos.', 'def_en' => 'A 4-hour slot of the schedule on the 5C website. A shift has 2 blocks.', 'tela' => 'grade'],
        ['termo' => 'Núcleo', 'termo_en' => 'Core', 'def' => 'Grupo fixo de SRs de uma unidade e turno, com um Operational Supervisor (OS). São 27 núcleos; a cada dia 2 dos 3 núcleos do turno trabalham.', 'def_en' => 'A fixed group of SRs in one unit and shift, led by an Operational Supervisor (OS). There are 27 cores; each day 2 of the 3 cores of a shift work.', 'tela' => 'organograma'],
        ['termo' => 'Posto', 'termo_en' => 'Post', 'def' => 'Uma ou mais páginas que um SR atende junto num turno, vindo do Capacity. Tem a vaga do dono e a de cobertura.', 'def_en' => 'One or more pages one SR handles together in a shift, taken from Capacity. It has an owner slot and a coverage slot.', 'tela' => 'grade'],
        ['termo' => 'Vaga fixa (equipe da vaga)', 'termo_en' => 'Fixed slot (slot team)', 'def' => 'Quem costuma ocupar a vaga de um posto. É preferência do motor, não trava: se a pessoa folga, outra do núcleo cobre. Todo posto tem equipe: a vaga vazia é completada sozinha antes de gerar (do núcleo, depois do turno; quem conhece a página primeiro).', 'def_en' => 'Who usually takes a post slot. It is a preference for the engine, not a lock: if the person is off, someone else from the core covers. Every post has a team: an empty slot is filled automatically before generating (from the core, then the shift; whoever knows the page first).', 'tela' => 'colaboradores'],
        ['termo' => 'Ciclo de 21 dias (5x2)', 'termo_en' => '21-day cycle (5x2)', 'def' => 'Rodízio de trabalho e folga do modelo 5x2, com no máximo 5 dias seguidos. Os 3 núcleos do turno ficam defasados no ciclo.', 'def_en' => 'The work and day-off rotation of the 5x2 model, with at most 5 days in a row. The 3 cores of a shift are offset in the cycle.', 'tela' => 'modelos'],
        ['termo' => 'Folga juntos', 'termo_en' => 'Days off together', 'def' => 'Par de pessoas (casal) que precisa folgar nos mesmos dias. Folgam juntas quando estão no mesmo ponto do ciclo de 21 dias: SR e OS no núcleo de mesmo número, OC e OA no mesmo ciclo do Roster. Cadastro e ajuste em Pessoas › Folga juntos.', 'def_en' => 'A pair of people (a couple) who need the same days off. They are off together when they are at the same point of the 21-day cycle: SR and OS in a core with the same number, OC and OA in the same Roster cycle. Set up and adjusted in People › Days off together.', 'tela' => 'casais'],
        ['termo' => 'Overlap', 'termo_en' => 'Overlap', 'def' => 'O 15º dia de trabalho do ciclo de 21 dias: o SR vai para a página 5C Schedule e sai com -5 no CSV (ou cobre lacuna). Cada SR tem um dia fixo (segunda, quarta ou quinta da semana do ciclo, guardado em esc_sr_overlap desde a 1.36.0), que não muda quando alguém entra ou sai do núcleo, e nunca cai no sábado ou no domingo do fim de semana completo. Na liderança, é a segunda depois do fim de semana, quando os 3 do grupo estão no turno.', 'def_en' => 'The 15th work day of the 21-day cycle: the SR goes to the 5C Schedule page with -5 in the CSV (or covers a gap). Each SR has a fixed day (Monday, Wednesday or Thursday of the cycle week, kept in esc_sr_overlap since 1.36.0), which does not change when someone joins or leaves the group, and never falls on the Saturday or Sunday of the full weekend off. For leadership, it is the Monday after the weekend, when the 3 people of the group are on shift.', 'tela' => 'grade'],
        ['termo' => 'Buffer de plantão', 'termo_en' => 'On-call buffer', 'def' => 'SR que está no turno mas sem posto. Vai para a página 5C Schedule com -2 no CSV e cobre faltas. A quantidade pedida vem do Capacity, já com absenteísmo.', 'def_en' => 'An SR on shift without a post. Goes to the 5C Schedule page with -2 in the CSV and covers absences. The requested amount comes from Capacity, already including absenteeism.', 'tela' => 'buffers'],
        ['termo' => 'Lacuna', 'termo_en' => 'Gap', 'def' => 'Bloco de uma página sem ninguém na escala. Aparece em laranja na grade.', 'def_en' => 'A page block with nobody scheduled. Shown in orange on the grid.', 'tela' => 'grade'],
        ['termo' => 'Acima da capacidade (⚠)', 'termo_en' => 'Over capacity (⚠)', 'def' => 'Quando falta gente, um SR já alocado pode puxar páginas da lacuna até 30% acima da capacidade (v4_over_capacity_max), só da mesma agência das páginas que ele já faz. Ele entra cobrindo (não é dono nem conta para a semana seguinte) e cede a página quando houver gente. A célula ganha ⚠.', 'def_en' => 'When people are short, an SR already placed may pull gap pages up to 30% over capacity (v4_over_capacity_max), only from the same agency as the pages they already work. They come in covering (not as owner, and it does not count for the next week) and give the page up when people are available. The cell gets a ⚠.', 'tela' => 'grade'],
        ['termo' => 'Anomalia', 'termo_en' => 'Anomaly', 'def' => 'Dias seguidos de trabalho acima do limite do modelo (no 5x2, a partir do 6º). Publicar com anomalia pede "estou ciente".', 'def_en' => 'Consecutive work days above the model limit (in 5x2, from the 6th day). Publishing with anomalies requires "I am aware".', 'tela' => 'grade'],
        ['termo' => 'Rascunho, publicada e substituída', 'termo_en' => 'Draft, published and superseded', 'def' => 'O rascunho é a versão em edição. Ao publicar, ele vira a versão publicada da semana e a anterior vira substituída (só consulta).', 'def_en' => 'The draft is the version being edited. When published, it becomes the week\'s published version and the previous one becomes superseded (read-only).', 'tela' => 'gerar'],
        ['termo' => 'Recalcular × Gerar do zero', 'termo_en' => 'Recalculate × Generate from scratch', 'def' => 'Recalcular cria uma subversão (v1.1) e mantém os ajustes travados. Gerar do zero cria uma versão nova sem os ajustes.', 'def_en' => 'Recalculate creates a sub-version (v1.1) and keeps the locked adjustments. Generate from scratch creates a new version without them.', 'tela' => 'gerar'],
        ['termo' => 'Ajuste travado', 'termo_en' => 'Locked adjustment', 'def' => 'Célula ajustada à mão na grade. Os recálculos mantêm a célula como ficou.', 'def_en' => 'A cell adjusted by hand on the grid. Recalculations keep the cell as it is.', 'tela' => 'grade'],
        ['termo' => 'De→Para', 'termo_en' => 'Before→After', 'def' => 'Diferença célula a célula entre uma versão e a anterior (quem entra, quem sai, lacunas abertas e fechadas).', 'def_en' => 'Cell-by-cell difference between a version and the previous one (who comes in, who leaves, gaps opened and closed).', 'tela' => 'grade'],
        ['termo' => 'CSV T1–T6', 'termo_en' => 'T1–T6 CSV', 'def' => 'Arquivo de cada página para colar no site da 5C (Schedule Adjustment). Marcas: -2 buffer, -5 Overlap, -8 OS, -7 OC, -6 OA e # para assistente.', 'def_en' => 'The file for each page to paste on the 5C website (Schedule Adjustment). Marks: -2 buffer, -5 Overlap, -8 OS, -7 OC, -6 OA and # for assistant.', 'tela' => 'grade'],
        ['termo' => 'Capacity', 'termo_en' => 'Capacity', 'def' => 'Módulo que calcula a necessidade: postos por página e turno, buffers e absenteísmo. Antes de gerar, o 5C Escalas pede o recálculo de hoje e os postos da escala passam a seguir os dele; página ativa no site que não estava lá entra sozinha (a saída de página também recalcula).', 'def_en' => 'The module that computes demand: posts per page and shift, buffers and absenteeism. Before generating, 5C Escalas asks for today\'s recalculation and the schedule posts follow it; a page active on the website that was not there is added automatically (a page exit also recalculates).', 'tela' => 'analise'],
        ['termo' => 'Saída de página', 'termo_en' => 'Page exit', 'def' => 'Página que deixa a operação. Confira, veja a prévia e aplique: o Capacity fecha a página, os postos são refeitos e as semanas são geradas de novo.', 'def_en' => 'A page leaving the operation. Check it, see the preview and apply it: Capacity closes the page, posts are rebuilt and the weeks are regenerated.', 'tela' => 'saidas'],
        ['termo' => 'Troca de página', 'termo_en' => 'Page swap', 'def' => 'Página que muda de dono pelos lotes do Planner da estrutura antiga. A tela Trocas de página fica no menu Legado, só para admin.', 'def_en' => 'A page that changes owner through the old structure\'s Planner batches. The Page swaps screen is in the Legacy menu, admin only.', 'tela' => null],
        ['termo' => 'Indisponibilidade', 'termo_en' => 'Unavailability', 'def' => 'Pedido de um SR para não trabalhar num dia ou turno (um dia, vários dias ou recorrente). Só o aprovado vira folga no próximo recálculo.', 'def_en' => 'An SR\'s request not to work on a day or shift (one day, several days or recurring). Only approved requests become days off in the next recalculation.', 'tela' => 'aprovar'],
        ['termo' => 'Solicitação do SR', 'termo_en' => 'SR request', 'def' => 'Pedido de um SR para trabalhar como assistente ou em dupla (não sozinho), ou mudar de turno, núcleo ou unidade. O líder registra, o Planejamento aprova e aplica uma troca 1 por 1 com outro SR, a partir de uma data.', 'def_en' => 'An SR\'s request to work as an assistant or in a pair (not alone), or to change shift, core or unit. The leader records it, Planning approves it and applies a one-for-one swap with another SR from a given date.', 'tela' => 'solicitacoes'],
        ['termo' => 'Troca 1 por 1', 'termo_en' => 'One-for-one swap', 'def' => 'Duas pessoas trocam de lugar: cada uma vai para o núcleo da outra e assume as vagas fixas dela. Nenhum posto fica sem dono e o nível de cada uma não muda.', 'def_en' => 'Two people swap places: each one moves to the other\'s core and takes the other\'s fixed slots. No post is left without an owner and each person keeps their level.', 'tela' => 'solicitacoes'],
        ['termo' => 'Owner e backup', 'termo_en' => 'Owner and backup', 'def' => 'Owner é quem tem a vaga de dono do posto da página (núcleo dono); backup é quem tem a vaga de cobertura (outro núcleo, nos dias de folga do dono). Veja em Páginas › Owners e backups.', 'def_en' => 'Owner is whoever holds the owner slot of the page post (owning core); backup is whoever holds the cover slot (another core, on the owner\'s days off). See Pages › Owners and backups.', 'tela' => 'owners'],
        ['termo' => 'Política de páginas', 'termo_en' => 'Page policy', 'def' => 'Regra que mede o atingimento da meta 5CReps de cada página na unidade e em cada turno. Abaixo de 85% o prazo corre (3 a 14 dias, conforme o atingimento); vencido, o sistema sugere trocar o owner ou a unidade. Em Ajuda › Regras.', 'def_en' => 'Rule that measures attainment of the 5CReps target of each page in the unit and in each shift. Below 85% the deadline runs (3 to 14 days, depending on attainment); once missed, the system suggests changing the owner or the unit. In Help › Rules.', 'tela' => 'regras'],
        ['termo' => 'Hora extra', 'termo_en' => 'Overtime', 'def' => 'Cobertura de um posto ou buffer vazio por alguém fora da escala, por bloco de 4 h (T1 a T6), respeitando no máximo 12 h seguidas e 52 h na semana. Quem faz um turno de 8 h pode pegar o bloco vizinho. Para anunciar, a tela Horas extras baixa o PDF de Overtime a partir do dia e turno escolhidos.', 'def_en' => 'Covering an empty post or buffer with someone off schedule, by 4-hour block (T1 to T6), with at most 12 h in a row and 52 h a week. Someone on an 8-hour shift can take the neighbouring block. To announce it, the Overtime screen downloads the Overtime PDF from the chosen day and shift.', 'tela' => 'horas'],
        ['termo' => 'Página que entra no lugar', 'termo_en' => 'Page coming in instead', 'def' => 'Na prévia da saída de uma página, a página nova (do Funil ou do site da 5C) que ocupa o lugar dela: entra na mesma carteira e nos mesmos núcleos, e quem perdeu a vaga fixa passa para ela a partir da data de entrada. Até lá, quem fica sem página vira buffer (-2) se falta gente no turno, ou sai da escala nesses dias.', 'def_en' => 'In a page exit preview, the new page (from the Funnel or the 5C website) that takes its place: it joins the same portfolio and cores, and whoever lost their fixed slot moves to it from the entry date. Until then, whoever is left without a page becomes buffer (-2) if the shift is short of people, or leaves the schedule on those days.', 'tela' => 'saidas'],
        ['termo' => 'Capacity: precisa e tem', 'termo_en' => 'Capacity: needs and has', 'def' => 'O Capacity (5c_planning) calcula os postos de cada unidade e turno e quantas pessoas precisa: titulares (postos × 1,5, pelo 5x2 de 21 dias) mais o buffer (faltas e picos). "Tem" são os SRs com cadastro no 5C Escalas (desde 09/11; antes, a foto de 27/10), guardados dia a dia desde 01/11 (fc_quadro_dia). O absenteísmo conta de 01/11 em diante. Quem é SR no RH e não está em nenhuma unidade aparece em Fora das unidades. Falta = precisa − tem. Uma versão por cálculo; o Capacity não entra no corte de 01/11.', 'def_en' => 'Capacity (5c_planning) calculates the posts of each unit and shift and how many people are needed: main SRs (posts × 1.5, from the 21-day 5x2) plus buffer (absences and peaks). "Has" is the SRs with a record in 5C Escalas (since 11/09; before that, the 10/27 snapshot), kept day by day since 11/01 (fc_quadro_dia). Absenteeism counts from 11/01 on. SRs who are in HR but in no unit appear in Outside the units. Shortfall = needs − has. One version per calculation; Capacity is not affected by the 11/01 cutoff.', 'tela' => 'capacity'],
        ['termo' => 'Ocupação dos postos', 'termo_en' => 'Post occupancy', 'def' => 'Na tela Capacity: SRs escalados por dia nas páginas de cada carteira (plano atual da semana) ÷ postos do Capacity. Buffer, Overlap, treinamento e liderança não contam. Abaixo de 90% o número fica laranja; acima de 100% há mais SRs que postos (ex.: escala montada pelo OM).', 'def_en' => 'On the Capacity screen: SRs scheduled per day on each portfolio\'s pages (current plan of the week) ÷ Capacity posts. Buffer, Overlap, training and leadership do not count. Below 90% the number turns orange; above 100% there are more SRs than posts (e.g. a schedule built by the OM).', 'tela' => 'capacity'],
        ['termo' => 'Requisição de vagas', 'termo_en' => 'Job requisition', 'def' => 'O pedido de contratação ao recrutamento, por turma (data de início do treinamento) e turno. Etapas: planejada (só no plano do Capacity) → requisição aberta → contratada → em treinamento → operando. Abrir até = início da turma menos o prazo de recrutamento (14 dias). Fica em Quadro e contratação › Requisição de vagas.', 'def_en' => 'The hiring request to recruitment, per class (training start date) and shift. Stages: planned (only in the Capacity plan) → requisition open → hired → in training → operating. Open by = class start minus the recruitment lead time (14 days). It is in Headcount & hiring › Job requisitions.', 'tela' => 'requisicao'],
        ['termo' => 'Destino do novato', 'termo_en' => 'New hire destination', 'def' => 'Unidade e núcleo onde o trainee entra depois do treinamento, no turno da turma. O sistema sugere a unidade com mais lacunas na escala da semana em que a turma fica disponível (no empate, a com mais falta no Capacity) e, dentro dela, o núcleo com menos SRs para a parte dele. O WFM confirma ou troca; o cadastro em Colaboradores é o que põe a pessoa na escala.', 'def_en' => 'Unit and core the trainee joins after training, in the class shift. The system suggests the unit with the most gaps in the schedule of the week the class becomes available (on a tie, the one with the largest Capacity shortfall) and, within it, the core with the fewest SRs for its share. WFM confirms or changes it; the record in Employees is what puts the person on the schedule.', 'tela' => 'treinamento'],
        ['termo' => 'New Hire e trainee (-4)', 'termo_en' => 'New Hire and trainee (-4)', 'def' => 'Recém-contratado em treinamento (em geral 14 dias). A turma é lida do e-mail do Treinamento em Quadro e contratação › Turmas de treinamento; confirmada, os trainees vão para a página 5C Schedule com -4 no CSV, de segunda a sexta no horário da turma. Ficam fora da escala normal até o dia disponível para a operação.', 'def_en' => 'Newly hired person in training (usually 14 days). The class is read from the Training e-mail in Headcount & hiring › Training classes; once confirmed, trainees go on the 5C Schedule page with -4 in the CSV, Monday to Friday in the class hours. They stay out of the regular schedule until the day they are available for operation.', 'tela' => 'treinamento'],
        ['termo' => 'Página emprestada para treinamento', 'termo_en' => 'Page lent for training', 'def' => 'A menor página de um posto com 2 ou mais páginas, cedida à turma o ciclo inteiro. Nunca OFTV (final OFTV ou número com t, ex.: 141t), nem página com mês abaixo de 85% ou com prioridade fixa, e evita a mesma página em dois turnos ao mesmo tempo (dá para usar, com aviso). O dono do turno continua dono e com a comissão. Nos dias e horário da turma o gerador não escala ninguém nela: o SR fica com as outras páginas do posto ou, se o posto só tinha ela, vai para uma página com lacuna no mesmo horário. Até 4 trainees por página, de 5 a 8 em 2, 9 ou mais em 3.', 'def_en' => 'The smallest page of a post with 2 or more pages, lent to the class for the whole cycle. Never OFTV (ending in OFTV or a number with t, e.g. 141t), nor a page with a month below 85% or a fixed priority, and avoids the same page on two shifts at the same time (allowed, with a warning). The shift owner stays the owner and keeps the commission. On the class days and hours the generator puts no one on it: the SR keeps the other pages of the post or, if the post only had it, moves to a page with a gap at the same time. Up to 4 trainees per page, 5 to 8 in 2, 9 or more in 3.', 'tela' => 'treinamento'],
        ['termo' => 'Arquétipo (volume de página nova)', 'termo_en' => 'Archetype (new page volume)', 'def' => 'Fãs/h médios das páginas do mesmo tier e perfil (Main, VIP, Free, OFTV) com chat no último mês. É o volume de uma página nova no Funil e no Capacity até ela ter chat próprio.', 'def_en' => 'Average fans/h of pages with the same tier and profile (Main, VIP, Free, OFTV) with chat in the last month. It is the volume of a new page in the Funnel and in Capacity until it has its own chat.', 'tela' => 'funil'],
        ['termo' => 'Faturamento de 30 dias (da página e da modelo)', 'termo_en' => '30-day revenue (page and model)', 'def' => 'O que ordena a escala: vendas fechadas e pendentes dos últimos 30 dias. Página com menos dias de venda tem a média emulada para 30 dias; sem venda nenhuma, vale o meio da faixa do tier. As páginas da mesma modelo somam: a modelo que mais fatura é preenchida primeiro, com todas as páginas dela.', 'def_en' => 'What orders the schedule: completed and pending sales in the last 30 days. A page with fewer days of sales has its average projected to 30 days; with no sales at all, the middle of its tier range is used. Pages of the same model add up: the model with the highest revenue is filled first, with all of its pages.', 'tela' => 'paginas'],
        ['termo' => 'Cor da página (sensibilidade)', 'termo_en' => 'Page flag (sensitivity)', 'def' => 'Vermelha: só recebe SR que já trabalhou na modelo dela (7 dias ou mais em 90, em qualquer página da modelo: Mikayla Free ou Mikayla Paid valem para as duas) ou é da equipe fixa dela; sem ninguém assim, fica em lacuna. Antes do melhor SR de cima para baixo, quem conhece a vermelha fica reservado para ela. Amarela: dá preferência a quem a conhece; a cota de no máximo 20% dos turnos da semana com gente nova ainda está desligada. Verde: segue o KPI. A cor vem da bandeira da entrada no Telegram ou do cadastro do cliente e muda em Páginas › Configuração das páginas. Vale no Gerar desde a 1.19.17.', 'def_en' => 'Red: only gets SRs who have worked on its model (7 days or more in 90, on any page of the model: Mikayla Free or Mikayla Paid count for both) or are on its fixed team; with no one like that, it stays as a gap. Before the best SR top-down, whoever knows a red page is reserved for it. Yellow: prefers people who know it; the cap of at most 20% of the week\'s shifts with new people is still off. Green: follows the KPI. The flag comes from the entry flag on Telegram or from the client record and is changed in Pages › Page settings. Used by Generate since 1.19.17.', 'tela' => 'paginas'],
        ['termo' => 'Plataforma da página', 'termo_en' => 'Page platform', 'def' => 'OnlyFans, Fanvue, Privacy, PlayBoy e outras. Vem da tela Páginas › Configuração das páginas ou, sem ela, do cadastro da página. O Gerar usa a plataforma: uma plataforma por turno (quem faz Privacy, Fanvue ou PlayBoy não acumula nem cobre página de outra plataforma no mesmo turno) e a Privacy só com SR brasileiro. Na Privacy, os valores do PDF saem em R$.', 'def_en' => 'OnlyFans, Fanvue, Privacy, PlayBoy and others. It comes from Pages › Page settings or, if not set there, from the page record. Generate uses the platform: one platform per shift (whoever works Privacy, Fanvue or PlayBoy does not stack or cover a page of another platform in the same shift) and Privacy only with Brazilian SRs. On Privacy, PDF amounts are in R$.', 'tela' => 'paginas'],
        ['termo' => 'Uma plataforma por turno', 'termo_en' => 'One platform per shift', 'def' => 'Desde a 1.19.15: no mesmo turno, o SR só faz páginas de uma plataforma. Quem faz Privacy, Fanvue ou PlayBoy não acumula nem cobre página do OnlyFans (nem o contrário). Vale no Gerar e no Recalcular com o mínimo de mudanças, que deixa de manter a mistura da versão publicada: fica a página da Privacy, Fanvue ou PlayBoy.', 'def_en' => 'Since 1.19.15: in the same shift, an SR only works pages of one platform. Whoever works Privacy, Fanvue or PlayBoy does not stack or cover an OnlyFans page (nor the other way round). It applies to Generate and to Recalc With Minimum Changes, which no longer keeps a mix from the published version: the Privacy, Fanvue or PlayBoy page stays.', 'tela' => 'paginas'],
        ['termo' => 'Alocação da página (Active team, On demand, Exclusiva)', 'termo_en' => 'Page allocation (Active team, On demand, Exclusive)', 'def' => 'Active team é o padrão: a página recebe gente pelo Gerar. On demand: o Gerar não põe ninguém; quando pedem, a alocação é feita à mão na Grade, com a célula travada. Exclusiva (solo): o SR da página não acumula nem cobre outra página; ela só tem assistente quando o posto é de 2 pessoas. Muda em Páginas › Configuração das páginas.', 'def_en' => 'Active team is the default: the page gets people through Generate. On demand: Generate puts no one on it; when asked, the allocation is done by hand on the Grid, with the cell locked. Exclusive (solo): the page\'s SR does not stack or cover another page; it only has an assistant when the post is for 2 people. Changed in Pages › Page settings.', 'tela' => 'paginas'],
        ['termo' => 'Restrições dos OM', 'termo_en' => 'OM restrictions', 'def' => 'Pedidos dos OMs sobre pessoas e páginas: equipe fixa (main e cover), divisão, só assistente, proibido na página, baixo fluxo, só uma página, só estas páginas, várias páginas, serve como assistente, não faz assistente, solo (nem assistente nem com assistente), tier médio, tier médio ou alto, faixa de faturamento, preferência por página masculina ou por certas páginas, não subordinado e inegociáveis. A tela Páginas › Restrições dos OM mostra tudo, lido do banco na hora, com PDF por unidade para mandar às equipes, e no painel Gerenciar as restrições dá para desativar, ativar, editar e apagar cada uma, ou em lote. Na Configuração das páginas, o botão PDF de cada página traz a configuração dela.', 'def_en' => 'Requests from the OMs about people and pages: fixed team (main and cover), split, assistant only, banned from the page, low flow, one page only, these pages only, several pages, works as assistant, does not work as assistant, solo (neither as nor with an assistant), mid tier, mid or high tier, revenue range, preference for male pages or for certain pages, not a subordinate and non-negotiables. Pages › OM restrictions shows all of them, read live from the database, with a PDF per unit to send to the teams, and the Manage restrictions panel deactivates, activates, edits and deletes each one, or in batches. In Page settings, each page\'s PDF button has its own setup.', 'tela' => 'fixacoes'],
        ['termo' => 'Equipe fixa da página (main e cover)', 'termo_en' => 'Page fixed team (main and cover)', 'def' => 'SRs que entram antes de todos na página, por turno. Primeiro os titulares (main) de todas as páginas, depois quem cobre (cover) e por último o resto da equipe. O membro deve ser da unidade da página: desde a 1.35.0, quem é de outra unidade não entra (só à mão, travado na Grade). No dia de treinamento (Overlap), quem é da equipe cobre primeiro a lacuna da própria página.', 'def_en' => 'SRs who go on the page before everyone else, per shift. First the main SRs of all pages, then the covers and last the rest of the team. A member should be from the page\'s unit; since 1.35.0, someone from another unit does not come in (only by hand, locked on the Grid). On the training day (Overlap), a team member covers their own page\'s gap first.', 'tela' => 'fixacoes'],
        ['termo' => 'Divisão do SR (50/50)', 'termo_en' => 'SR split (50/50)', 'def' => 'O SR reparte os turnos em que está disponível entre as páginas da lista, na parte de cada uma (ex.: 50% numa e 50% noutra) (só páginas da unidade dele, desde a 1.35.0). O que faltar para 100% é a escala normal da unidade dele. A cada dia a vez é da página mais atrasada na parte dela. A divisão vem antes da equipe fixa, e a página da divisão vale sempre para quem divide.', 'def_en' => 'The SR splits the shifts they are available for among the pages on the list, in each one\'s share (e.g. 50% on one and 50% on another; only pages of their own unit, since 1.35.0). Whatever is missing to 100% is the regular schedule of their unit. Each day the turn goes to the page furthest behind its share. The split comes before the fixed team, and the split page always applies to the person splitting.', 'tela' => 'fixacoes'],
        ['termo' => 'Só assistente', 'termo_en' => 'Assistant only', 'def' => 'A pessoa só entra em posto de assistente, de qualquer nível, e não acumula nem cobre página. Diferente de "serve como assistente", que só dá a ela a vez no posto de assistente, e de "não faz assistente".', 'def_en' => 'The person only takes assistant posts, at any level, and does not stack or cover pages. Different from "works as assistant", which only gives them priority for the assistant post, and from "does not work as assistant".', 'tela' => 'fixacoes'],
        ['termo' => 'Baixo fluxo', 'termo_en' => 'Low flow', 'def' => 'Baixo fluxo: só posto de até 12 fãs/h (parâmetro v4_baixo_fluxo_max) ou de assistente; não acumula nem cobre. Baixo fluxo estrito: nunca em posto acima desse corte, nem de assistente.', 'def_en' => 'Low flow: only posts up to 12 fans/h (parameter v4_baixo_fluxo_max) or assistant posts; no stacking or covering. Strict low flow: never on a post above that cut, not even as assistant.', 'tela' => 'fixacoes'],
        ['termo' => 'Só uma página / Várias páginas ao mesmo tempo', 'termo_en' => 'One page only / Several pages at once', 'def' => 'Só uma página: a pessoa não fica em posto com mais de uma página (fora as de apoio), não acumula outro posto nem cobre página. Várias páginas ao mesmo tempo: no turno dele, o SR pega todos os postos que só têm páginas da lista dele, acumulando, sem assistente e sem limite de capacidade.', 'def_en' => 'One page only: the person is not put on a post with more than one page (support pages aside), does not stack another post and does not cover pages. Several pages at once: in their shift, the SR takes every post that only has pages from their list, stacking them, with no assistant and no capacity limit.', 'tela' => 'fixacoes'],
        ['termo' => 'Restrições que fecham sozinhas', 'termo_en' => 'Restrictions that close by themselves', 'def' => 'Desde a 1.19.16: quando uma página sai ou um SR é desligado, as restrições dele fecham sozinhas no último dia. A pessoa sai da equipe fixa (o resto da equipe continua), e fecham o só assistente, o proibido e a divisão; as listas (só uma página, várias páginas, só estas páginas e as outras) perdem quem saiu e a página que saiu. Roda no fim da saída de página e antes de cada Gerar. Quem passou para a liderança (OS, OC, OM, OA) não conta como desligado.', 'def_en' => 'Since 1.19.16: when a page leaves or an SR is let go, their restrictions close by themselves on the last day. The person leaves the fixed team (the rest of the team stays), and assistant only, banned and split close; the lists (one page only, several pages, these pages only and the others) drop whoever left and the page that left. It runs at the end of a page exit and before each Generate. Someone who moved to leadership (OS, OC, OM, OA) does not count as let go.', 'tela' => 'fixacoes'],
        ['termo' => 'Página bloqueada depois da saída (60 dias)', 'termo_en' => 'Page blocked after exit (60 days)', 'def' => 'A página que saiu pela tela Saídas de página não volta sozinha por 60 dias (parâmetro v4_saida_bloqueio_dias), mesmo que continue ativa no site. Quando ela fica ativa de novo, aparece em Funil de entrada › Ativas no site, fora da escala como "não volta sozinha", e o Gerar avisa. Ali você põe a página na escala (na carteira de antes ou em outra) ou a ignora.', 'def_en' => 'A page that left through the Page exits screen does not come back by itself for 60 days (parameter v4_saida_bloqueio_dias), even if it is still active on the website. When it becomes active again, it shows up in Intake funnel › Active on the website, outside the schedule as "does not come back by itself", and Generate warns about it. There you put the page in the schedule (in its previous portfolio or another one) or ignore it.', 'tela' => 'funil'],
        ['termo' => 'Ativas no site, fora da escala', 'termo_en' => 'Active on the website, outside the schedule', 'def' => 'Seção do Funil de entrada que não vem do CRM: lista as páginas ativas no site da 5C (5c_pages) sem carteira no Capacity, como nova ou retorno (já esteve no Capacity ou na escala), com o dia em que ficou ativa, a carteira de antes, os dias com escala no site e a venda. Pôr na escala grava a carteira no Capacity e recalcula; os postos entram no próximo Gerar, no núcleo (OS) escolhido ou no automático. Ignorar serve para página que não é de escala (PH, X, MYM, teste); se ela sair e voltar, aparece de novo.', 'def_en' => 'Intake funnel section that does not come from the CRM: it lists the pages active on the 5C website (5c_pages) with no portfolio in Capacity, as new or return (already in Capacity or in the schedule), with the day it became active, the previous portfolio, the days scheduled on the website and the sales. Put in the schedule saves the portfolio in Capacity and recalculates; the positions enter at the next Generate, in the chosen core (OS) or the automatic one. Ignore is for pages that are not scheduled (PH, X, MYM, test); if the page leaves and comes back, it shows up again.', 'tela' => 'funil'],
        ['termo' => 'A partir de e "Antes do corte, igual ao site"', 'termo_en' => 'From and "Before the cut-off, same as the website"', 'def' => 'No Gerar, "A partir de" (dia e turno) é o corte: só muda o que vem depois dele. A opção "Antes do corte, igual ao site", marcada por padrão, copia as células de antes do corte da escala oficial do site (5C Schedule), como estão, em vez da versão publicada. Na Grade, o "CSV a partir de" faz o mesmo no CSV e nos PDFs: no dia do corte, os blocos de antes dele saem iguais ao site.', 'def_en' => 'In Generate, "From" (day and shift) is the cut-off: only what comes after it changes. The option "Before the cut-off, same as the website", ticked by default, copies the cells before the cut-off from the official schedule on the website (5C Schedule), as they are, instead of the published version. On the Grid, "CSV from" does the same for the CSV and the PDFs: on the cut-off day, the blocks before it come out the same as the website.', 'tela' => 'gerar'],
        ['termo' => 'Tags de leitura', 'termo_en' => 'Reading tags', 'def' => 'Chips curtos ao lado de cada SR na Grade e no PDF das páginas: Meta ✓ / Meta ✗ (na modelo, todas as páginas dela, 30 dias), Exp. / Inexp. (dias na modelo em 90; conhecer uma das páginas da modelo basta), Trainee, Faltas, SLA ↓, P&G, KPI ↑ / ↓ e Seq. meta. Vermelho e laranja são risco; verde ajuda. Na grade aparecem só os riscos; no detalhe da célula, todas. "⚠ n" ao lado da página conta os SRs com tag vermelha no turno.', 'def_en' => 'Short chips next to each SR on the Grid and in the pages PDF: Goal ✓ / Goal ✗ (on the model, all its pages, 30 days), Exp. / Inexp. (days on the model in 90; knowing one of the model\'s pages is enough), Trainee, Absences, SLA ↓, P&G, KPI ↑ / ↓ and Goal streak. Red and orange are risks; green helps. The grid shows only the risks; the cell detail shows all of them. "⚠ n" next to the page counts the SRs with a red tag in the shift.', 'tela' => 'grade'],
        ['termo' => 'Versão do documento (vN)', 'termo_en' => 'Document version (vN)', 'def' => 'Organograma, escala da liderança, KPI, regras, owners e restrições dos OM mostram "versão vN" no cabeçalho e no nome do arquivo. O número só sobe quando o conteúdo impresso muda: imprimir de novo o mesmo conteúdo mantém o número. Os PDFs e CSVs da escala das páginas levam a versão do plano (ex.: v32.1).', 'def_en' => 'Org chart, leadership schedule, KPI, rules, owners and OM restrictions show "version vN" in the header and in the file name. The number only goes up when the printed content changes: printing the same content again keeps the number. The pages schedule PDFs and CSVs carry the plan version (e.g. v32.1).', 'tela' => 'regras'],
        ['termo' => 'Página desconsiderada', 'termo_en' => 'Disregarded page', 'def' => 'Página sem SLA a cumprir: carga zero no posto, última a receber gente e fora dos postos do Capacity (fica de apoio no posto da mesma modelo). No automático é a OFTV (ou código terminado em t) que faturou menos de US$ 8 mil em 30 dias (parâmetro v4_trivial_receita_min). Muda em Páginas › Configuração das páginas.', 'def_en' => 'A page with no SLA to meet: zero load in the post, last to get people and out of the Capacity posts (it becomes support in the same model\'s post). On automatic it is an OFTV page (or a code ending in t) that made less than US$ 8k in 30 days (parameter v4_trivial_receita_min). Changed in Pages › Page settings.', 'tela' => 'paginas'],
        ['termo' => 'Falha administrativa (AF)', 'termo_en' => 'Administrative failure (AF)', 'def' => 'Falta que não é culpa do SR: escala dobrada (estava em outra página no mesmo horário) ou fora do horário dele. Vem da classificação oficial do absenteísmo (abs_adh_af) e não conta no absenteísmo do KPI nem no realizado da Análise.', 'def_en' => 'Absence that is not the SR\'s fault: double scheduling (on another page at the same time) or outside their shift. It comes from the official absenteeism classification (abs_adh_af) and does not count in KPI absenteeism or in the actual rate in Analysis.'],
        ['termo' => 'Mérito (Legacy)', 'termo_en' => 'Merit (Legacy)', 'def' => 'Indicador antigo, em pontos (tier da página, meta, faltas, SLA, tempo de casa, venda por hora, cargo antigo, infrações e sequência na meta). Desde a 1.38.0 fica na área Legacy, só leitura, com os dados preservados; o indicador oficial é o KPI dos SRs. Só o admin vê.', 'def_en' => 'Former points-based indicator (page tier, goal, absences, SLA, tenure, sales per hour, old role, infractions and goal streak). Since 1.38.0 it sits in the Legacy area, read only, with the data preserved; the official indicator is the SR KPI. Admin only.', 'tela' => 'merito'],
        ['termo' => 'KPI (Kinetic, Process & Integrity)', 'termo_en' => 'KPI (Kinetic, Process & Integrity)', 'def' => 'O indicador oficial de desempenho dos SRs (desde a 1.38.0; referência da escala desde a 1.34.0). Score = Kinetic (meta) × Process (SLA 5, 10 e 15) × Integrity (faltas e quebra de P&G), de 0% a 120%, nas 4 últimas semanas fechadas (pesos 4-3-2-1). Cada SR tem um nível de 0 a 4 que define a ordem no Gerar.', 'def_en' => 'The official SR performance indicator (since 1.38.0; the schedule reference since 1.34.0). Score = Kinetic (goal) × Process (SLA 5, 10 and 15) × Integrity (absences and P&G breaches), from 0% to 120%, over the last 4 closed weeks (weights 4-3-2-1). Each SR has a level from 0 to 4 that sets the order in Generate.', 'tela' => 'kpi'],
        ['termo' => 'Nível do KPI (0 a 4)', 'termo_en' => 'KPI level (0 to 4)', 'def' => '4 = 120% (vem primeiro nas páginas maiores); 3 = 100% a 119% (só perde o posto para o 4); 2 = mantém a posição (75% a 99%, novato com 75% provisório e quem está fora dos 20% piores); 1 = entre os 20% piores com 50% a 74% (perde o posto para 3 ou 4); 0 = entre os 20% piores abaixo de 50% (fora das páginas prioritárias e último no acúmulo e na sobrecarga; abaixo de 25%, só cobertura). No máximo 20% dos SRs mudam de posto pelo KPI na semana.', 'def_en' => '4 = 120% (first on the biggest pages); 3 = 100% to 119% (only loses the post to a 4); 2 = keeps position (75% to 99%, new hire with provisional 75% and those outside the worst 20%); 1 = among the worst 20% with 50% to 74% (loses the post to a 3 or 4); 0 = among the worst 20% below 50% (off priority pages and last for stacking and overload; below 25%, cover only). At most 20% of SRs change post because of the KPI in a week.', 'tela' => 'kpi'],
        ['termo' => 'Base da semana anterior (80/20)', 'termo_en' => 'Previous week baseline (80/20)', 'def' => 'Desde a 1.37.0, o Gerar parte das páginas de cada SR na semana anterior (página da base = a que teve 25% ou mais dos blocos dele). O motor roda uma vez livre e lista as trocas que faria; só 20% delas acontecem, as de maior impacto (faturamento da página no turno × diferença de score do KPI entre quem entra e quem sai). Mudança de unidade, turno ou núcleo conta nesses 20%; saída, página que saiu, equipe fixa e célula travada à mão ficam fora da conta. Os outros SRs ficam na página da semana anterior, e quem fez a página na semana anterior conta como quem conhece a página.', 'def_en' => 'Since 1.37.0, Generate starts from each SR\'s pages in the previous week (baseline page = one with 25% or more of their blocks). The engine runs once freely and lists the swaps it would make; only 20% of them happen, the ones with the biggest impact (page revenue in the shift × KPI score difference between who comes in and who leaves). A change of unit, shift or core counts in those 20%; exits, pages that left, fixed teams and cells locked by hand are left out of the count. The other SRs stay on the previous week\'s page, and whoever worked the page in the previous week counts as knowing it.', 'tela' => 'movimentos'],
        ['termo' => 'Anjo do OS', 'termo_en' => 'OS Angel', 'def' => 'Cada OS pode escolher 1 SR do núcleo dele que ia mudar de página por troca do motor (80/20) para ficar mais uma semana na página atual. O Planejamento registra em Escala › Movimentações e Anjos; vale no próximo Gerar ou recálculo da semana.', 'def_en' => 'Each OS can pick 1 SR from their core who was going to change page because of an engine swap (80/20) to stay one more week on the current page. Planning records it in Schedule › Moves and Angels; it applies at the next Generate or recalculation of the week.', 'tela' => 'movimentos'],
        ['termo' => 'Nível de SR (0 a 5)','termo_en' => 'SR level (0 to 5)', 'def' => 'Define a fatia de turnos em posto: SR 0 = 40%, SR 1 = 60%, SR 2 = 80%, SR 3 a 5 = 100%.', 'def_en' => 'Sets the share of shifts on a post: SR 0 = 40%, SR 1 = 60%, SR 2 = 80%, SR 3 to 5 = 100%.', 'tela' => 'srs'],
        ['termo' => 'OM, OC, OS e OA', 'termo_en' => 'OM, OC, OS and OA', 'def' => 'Operational Unit Manager (por unidade, não segue escala), Operational Coordinator (3 por turno), Operational Supervisor (um por núcleo) e Operational Assistant (1 por turno, 24/7).', 'def_en' => 'Operational Unit Manager (per unit, no schedule), Operational Coordinator (3 per shift), Operational Supervisor (one per core) and Operational Assistant (1 per shift, 24/7).', 'tela' => 'lideranca'],
        ['termo' => 'Roster da liderança', 'termo_en' => 'Leadership roster', 'def' => 'Quem é OM, OC, OS e OA a partir de cada data. Muda na tela Pessoas › Roster da liderança: quem entra sai do núcleo de SR e quem sai pode ficar com o lugar de quem entrou.', 'def_en' => 'Who is OM, OC, OS and OA from each date. It changes in People › Leadership roster: the newcomer leaves their SR core and the person leaving can take the newcomer\'s place.', 'tela' => 'roster'],
        ['termo' => 'Gerar em etapas', 'termo_en' => 'Generate in steps', 'def' => 'Ao gerar ou recalcular, uma tela de progresso cobre o sistema (o menu fica bloqueado) e mostra três etapas: Verificação (o que impede a escala de sair certa), Capacity (recalculado com os parâmetros de hoje) e Escala. Se uma etapa não passa, a tela diz o motivo e tem o botão para a tela que resolve, como Saídas de página quando falta conferir a saída de uma página. Queda de conexão repete a etapa sozinha.', 'def_en' => 'When you generate or recalculate, a progress screen covers the system (the menu is blocked) and shows three steps: Check (what keeps the schedule from coming out right), Capacity (recalculated with today\'s parameters) and Schedule. If a step does not pass, the screen says why and has a button to the screen that fixes it, such as Page exits when a page exit still needs checking. A dropped connection retries the step automatically.', 'tela' => 'gerar'],
        ['termo' => 'Virada', 'termo_en' => 'Switch-over', 'def' => 'Momento em que a estrutura nova passa a valer: 31/10 às 21:00, começando pelo turno D. Antes disso vale a escala já postada.', 'def_en' => 'When the new structure starts: Oct 31 at 21:00, starting with shift D. Before that, the schedule already posted applies.', 'tela' => 'gerar'],
        ['termo' => 'Legado', 'termo_en' => 'Legacy', 'def' => 'Telas da estrutura antiga: Configuração dos times (times e parties), só para consulta depois da virada, e Trocas de página (só admin).', 'def_en' => 'Screens of the old structure: Team setup (teams and parties), read-only after the switch-over, and Page swaps (admin only).', 'tela' => 'times'],
        ['termo' => 'Modo Treino', 'termo_en' => 'Training mode', 'def' => 'Cópia separada do sistema para praticar. Nada feito no treino muda a escala real; "Recomeçar o treino" volta tudo ao começo.', 'def_en' => 'A separate copy of the system for practice. Nothing done in training changes the real schedule; "Restart training" resets everything.', 'tela' => 'tutorial'],
        ['termo' => 'Código de ocorrência', 'termo_en' => 'Incident code', 'def' => 'Código de 6 letras e números que aparece em erro inesperado. Passe para o admin: ele acha o detalhe no log.', 'def_en' => 'A 6-character code shown on unexpected errors. Give it to the admin: it points to the details in the log.', 'tela' => null],
    ];
}

// FAQ: pergunta e resposta (pt / en).
function escFaq(): array {
    return [
        ['p' => 'Como incluo, mudo ou apago uma turma do plano?', 'p_en' => 'How do I add, change or delete a class in the plan?', 'r' => 'Em Quadro e contratação › Requisição de vagas, na tabela Turmas: "Adicionar turma" inclui uma turma em qualquer data (também intermediária), cada linha tem Salvar (data e números) e Apagar, e "Gravar turmas planejadas" salva todas as planejadas de uma vez. Turma com requisição aberta ou contratada muda no Acompanhamento das requisições; em treinamento não muda. Grava no plano do Capacity (fc_contratacoes).', 'r_en' => 'In Headcount & hiring › Job requisitions, in the Classes table: "Add class" adds a class on any date (also in between), each row has Save (date and numbers) and Delete, and "Save planned classes" saves all planned ones at once. A class with an open or hired requisition changes under Requisition tracking; one in training does not change. It writes to the Capacity plan (fc_contratacoes).'],
        ['p' => 'Onde vejo quem está no RH e sem unidade?', 'p_en' => 'Where do I see who is in HR with no unit?', 'r' => 'Em Quadro e contratação › Fora das unidades. Cada SR vem com a sugestão de unidade, turno e núcleo pelas lacunas; "Cadastrar" grava em Colaboradores. Liderança e trainees ficam de fora (os trainees estão em Turmas de treinamento).', 'r_en' => 'In Headcount & hiring › Outside the units. Each SR comes with a suggested unit, shift and core from the gaps; "Register" saves to Employees. Leadership and trainees are left out (trainees are in Training classes).'],
        ['p' => 'Por que o histórico começa em 01/11/2026?', 'p_en' => 'Why does the history start on 11/01/2026?', 'r' => 'Os dados anteriores estão comprometidos. KPI, metas, faltas, SLA, vendas e quem conhece cada página contam só a partir dessa data, mesmo quando a janela é maior. O Capacity segue como estava, e o Equilíbrio das unidades usa sempre o faturamento dos 30 dias anteriores.', 'r_en' => 'Earlier data is compromised. KPI, goals, absences, SLA, sales and who knows each page only count from that date, even when the window is longer. Capacity stays as it was, and Unit balance always uses the revenue of the previous 30 days.'],
        ['p' => 'O que o KPI muda na escala?', 'p_en' => 'What does the KPI change in the schedule?', 'r' => 'O KPI é o indicador oficial (o Mérito é Legacy). No Gerar, cada página escolhe primeiro quem bateu 65% da meta nela, depois o nível do KPI (4 a 0), o score e o tempo de casa. Quem está no posto só sai para alguém de nível que o tire (o 3 só sai para o 4; o 2 mantém), e no máximo 20% dos SRs mudam de posto pelo KPI na semana. O nível 0 fica fora das páginas prioritárias. O detalhe de cada SR está em Análise › KPI dos SRs.', 'r_en' => 'The KPI is the official indicator (Merit is Legacy). In Generate, each page first picks whoever hit 65% of its goal, then the KPI level (4 to 0), the score and tenure. Whoever is on the post only leaves for someone at a level that displaces them (a 3 only leaves for a 4; a 2 keeps), and at most 20% of SRs change post because of the KPI in a week. Level 0 stays off priority pages. Each SR\'s detail is in Analysis › SR KPI.'],
        ['p' => 'Por que o SR continuou na mesma página da semana passada?', 'p_en' => 'Why did the SR stay on the same page as last week?', 'r' => 'Desde a 1.37.0 a semana anterior é a base: cada SR fica nas páginas em que estava, e das trocas que o motor propõe só 20% acontecem, as de maior impacto (faturamento × ganho de KPI). O OS ainda pode escolher 1 Anjo, que fica mais uma semana. A lista de quem muda, quem fica e por quê está em Escala › Movimentações e Anjos.', 'r_en' => 'Since 1.37.0 the previous week is the baseline: each SR stays on the pages they had, and of the swaps the engine proposes only 20% happen, the ones with the biggest impact (revenue × KPI gain). The OS can also pick 1 Angel, who stays one more week. The list of who moves, who stays and why is in Schedule › Moves and Angels.'],
        ['p' => 'Como exporto o KPI dos SRs?', 'p_en' => 'How do I export the SR KPI?', 'r' => 'Em Análise › KPI dos SRs, escolha a unidade e o turno e use "Exportar .xlsx" ou "PDF". Só WFM, Planejamento e Admin veem a tela.', 'r_en' => 'In Analysis › SR KPI, choose the unit and shift and use "Export .xlsx" or "PDF". Only WFM, Planning and Admin see the screen.'],
        ['p' => 'Não vejo o KPI dos SRs nem Owners e backups no menu. Por quê?', 'p_en' => 'I do not see SR KPI or Owners and backups in the menu. Why?', 'r' => 'O KPI e os dados individuais ficam só para WFM, Planejamento e Admin. Se você precisa, peça a um administrador em Administração › Acessos.', 'r_en' => 'The KPI and individual data are only for WFM, Planning and Admin. If you need them, ask an administrator in Administration › Access.'],
        ['p' => 'Recalcular apaga os ajustes que fiz na grade?', 'p_en' => 'Does recalculating erase my grid adjustments?', 'r' => 'Não. Recalcular mantém os ajustes travados. Só "Gerar do zero" descarta, e o sistema pede confirmação mostrando quantos ajustes serão perdidos.', 'r_en' => 'No. Recalculate keeps locked adjustments. Only "Generate from scratch" discards them, and the system asks for confirmation showing how many will be lost.'],
        ['p' => 'Por que o Painel não recalcula sozinho?', 'p_en' => 'Why doesn\'t the Dashboard recalculate by itself?', 'r' => 'Para não mudar a versão por baixo de quem está editando e para poupar o servidor. Use "Verificar mudanças" no Painel ou em Gerar escala.', 'r_en' => 'So the version does not change under someone who is editing, and to save server load. Use "Check for changes" on the Dashboard or in Generate schedule.'],
        ['p' => 'Já postei a semana e preciso recalcular. Como mexo o mínimo no site?', 'p_en' => 'I already posted the week and need to recalculate. How do I change the website as little as possible?', 'r' => 'Em Gerar escala, use "Recalcular com o mínimo de mudanças": parte da versão publicada e só muda o necessário (página nova ou que saiu, quem ficou indisponível, turno dobrado). Quem falta é coberto pela pessoa que o cálculo novo indicaria, por um buffer da unidade ou como página a mais de quem tem pouca carga no bloco. Na postagem, as outras páginas ficam "igual". "Recalcular tudo" refaz a semana inteira e costuma mudar muitas páginas.', 'r_en' => 'In Generate schedule, use "Recalc With Minimum Changes": it starts from the published version and only changes what is needed (new or removed page, who became unavailable, double shift). Gaps are covered by the person the new calculation would pick, by a unit buffer or as an extra page for someone with low load in the block. When posting, the other pages show "same". "Recalculate everything" redoes the whole week and usually changes many pages.'],
        ['p' => 'A geração parou na Verificação. O que faço?', 'p_en' => 'Generation stopped at the Check step. What do I do?', 'r' => 'A tela diz o motivo e tem o botão para resolver. O caso mais comum é saída de página "a conferir": em Saídas de página, confirme (e aplique) ou marque "não saiu", e gere de novo. Pedido de indisponibilidade sem decisão só avisa: dá para continuar ou decidir antes. Se outra pessoa estiver gerando, espere terminar.', 'r_en' => 'The screen says why and has a button to fix it. The most common case is a page exit "to check": in Page exits, confirm it (and apply it) or mark "did not leave", then generate again. An unavailability request with no decision only warns: you can continue or decide first. If someone else is generating, wait for them to finish.'],
        ['p' => 'A escala usa o Capacity de quando?', 'p_en' => 'Which Capacity does the schedule use?', 'r' => 'O de hoje. Ao gerar ou recalcular uma semana, o sistema recalcula o Capacity (sempre, na etapa 2 da tela de progresso) e os postos passam a seguir os dele a partir de amanhã: posto igual continua com a equipe; posto que mudou fecha e a equipe vai para o posto novo com as páginas dela. A mensagem depois de gerar diz quantos ficaram iguais, novos e fechados.', 'r_en' => 'Today\'s. When you generate or recalculate a week, the system recalculates Capacity (always, in step 2 of the progress screen) and the posts follow it from tomorrow: an unchanged post keeps its team; a changed post closes and its team goes to the new post with its pages. The message after generating says how many stayed, are new and were closed.'],
        ['p' => 'Uma página ativa no site não estava no Capacity. O que acontece?', 'p_en' => 'A page active on the website was not in Capacity. What happens?', 'r' => 'Se tem escala ou venda nos últimos 28 dias, ela entra sozinha antes de gerar: na carteira da mesma modelo (ex.: Thalia 147t junto da Thalia 147m) ou, se a modelo é nova, no destino do Funil. O volume vem do arquétipo de uma página parecida até ela ter chat próprio. Página de outra plataforma, de teste ou sem movimento fica fora. OFTV sem faturamento entra com a menor prioridade do gerador.', 'r_en' => 'If it has a schedule or sales in the last 28 days, it is added automatically before generating: in the same model\'s portfolio (e.g. Thalia 147t with Thalia 147m) or, for a new model, in the Funnel destination. The volume comes from the archetype of a similar page until it has its own chat. Pages from other platforms, test pages or pages with no activity stay out. OFTV without revenue gets the generator\'s lowest priority.'],
        ['p' => 'Um posto pode ficar sem equipe (sem owner ou backup)?', 'p_en' => 'Can a post be left without a team (no owner or backup)?', 'r' => 'Não. Antes de cada geração, a vaga sem ninguém é completada com SRs do mesmo turno e unidade: do núcleo da vaga dentro da fatia, depois de outro núcleo, depois níveis 0–2 acima da fatia e, sem folga em ninguém, o menos carregado do núcleo. Quem conhece a página vem primeiro. A página ainda pode ficar vazia num dia em que falta gente (o gerador cobre a mais importante), mas o posto sempre tem a quem chamar. As vagas novas aparecem como proposta em Páginas › Owners e backups.', 'r_en' => 'No. Before each generation, a slot with no one is filled with SRs from the same shift and unit: from the slot\'s core within the share, then from another core, then levels 0–2 above their share and, if no one has room, the least loaded SR of the core. Whoever knows the page comes first. The page may still be empty on a day short of people (the generator covers the most important one), but the post always has someone to call. The new slots show as proposals in Pages › Owners and backups.'],
        ['p' => 'Publiquei. E agora?', 'p_en' => 'I published. What now?', 'r' => 'Vá em Grade da escala › Postar no site da 5C. Em cada página: Delete Range no site quando pedido, cole o CSV (Model = página, Date Schedule e Date End da semana) e marque "1 · Apaguei" e "2 · Postei".', 'r_en' => 'Go to Schedule grid › Post on the 5C website. For each page: Delete Range on the site when asked, paste the CSV (Model = page, Date Schedule and Date End of the week) and mark "1 · Deleted" and "2 · Posted".'],
        ['p' => 'Como sei quais páginas mudaram desde a última postagem?', 'p_en' => 'How do I know which pages changed since the last post?', 'r' => 'No cartão de cada página aparece "sem mudança desde vX" ou "mudou desde vX". Use o filtro "Sem mudança" para pular as que podem ficar como estão.', 'r_en' => 'Each page card shows "no change since vX" or "changed since vX". Use the "No change" filter to skip the ones that can stay as they are.'],
        ['p' => 'Onde posto a escala da liderança?', 'p_en' => 'Where do I post the leadership schedule?', 'r' => 'Pela Grade: OS, OC e OA saem no CSV da página 5C Schedule (-8, -7 e -6), já com os ajustes. A tela Escala da liderança é para conferir o rodízio e marca "≠ grade" onde o plano difere.', 'r_en' => 'Through the Grid: OS, OC and OA come out in the 5C Schedule page CSV (-8, -7 and -6), already with adjustments. The Leadership schedule screen is for checking the rotation and marks "≠ grid" where the plan differs.'],
        ['p' => 'Um SR pediu folga. Como entra na escala?', 'p_en' => 'An SR asked for a day off. How does it get into the schedule?', 'r' => 'Lance o pedido em Indisponibilidade (ou ele chega pela Nora/site). Aprovado, entra no próximo recálculo da semana.', 'r_en' => 'Enter the request in Unavailability (or it arrives through Nora/the website). Once approved, it goes into the week\'s next recalculation.'],
        ['p' => 'Aprovar só parte das datas de um pedido?', 'p_en' => 'Approve only some dates of a request?', 'r' => 'Marque as datas que aprova e use "Aprovar só as marcadas". As outras viram recusadas e pedem comentário, que vai para o colaborador.', 'r_en' => 'Tick the dates you approve and use "Approve checked only". The others become declined and need a comment, which goes to the employee.'],
        ['p' => 'Uma página saiu e outra vai entrar no lugar. Como faço?', 'p_en' => 'A page left and another one will take its place. What do I do?', 'r' => 'Em Saídas de página, clique em "Aplicar…" na saída e, na prévia, escolha a página que entra no lugar e a data. A prévia mostra os postos novos, quem passa para a página nova e o que acontece com cada pessoa nos dias até a entrada (buffer ou fora da escala, dá para trocar). Aplicar faz tudo de uma vez: Capacity, postos, equipe e semanas.', 'r_en' => 'In Page exits, click "Apply…" on the exit and, in the preview, choose the page coming in and the date. The preview shows the new posts, who moves to the new page and what happens to each person on the days until the entry (buffer or off the schedule, you can change it). Applying does it all at once: Capacity, posts, team and weeks.'],
        ['p' => 'Um SR quer fazer hora extra logo depois do turno. Pode?', 'p_en' => 'An SR wants to do overtime right after their shift. Can they?', 'r' => 'Pode, um bloco de 4 h: quem faz T2/T3 pega o T4 (ou o T1 antes) e fica em 12 h seguidas. Dois blocos a mais (16 h) o sistema recusa. Em Horas extras cada vazio aparece por bloco; registre o interesse no bloco e aloque.', 'r_en' => 'Yes, one 4-hour block: someone on T2/T3 takes T4 (or T1 before) and stays at 12 h in a row. Two more blocks (16 h) are refused. In Overtime each empty slot shows by block; record the interest on the block and allocate.'],
        ['p' => 'Uma página saiu. O que faço?', 'p_en' => 'A page left. What do I do?', 'r' => 'Em Saídas de página, confira a saída e clique em "Aplicar…". A prévia mostra postos que fecham, refeitos, SRs sem vaga e semanas geradas de novo. Confirme para aplicar.', 'r_en' => 'In Page exits, check the exit and click "Apply…". The preview shows posts that close, rebuilt posts, SRs without a slot and regenerated weeks. Confirm to apply.'],
        ['p' => 'A página saiu, mas não aparece em Saídas. O que faço?', 'p_en' => 'A page left, but it does not show in Exits. What do I do?', 'r' => 'O Capacity só gera a saída depois da foto das 3h. Se a página já foi desativada no site, ela aparece na hora em Saídas de página › "Desativadas no site, sem saída detectada": marque e veja a prévia. Se ainda está ativa no site, use "Aplicar saída de página" com a página (e "+ outra página" para a VIP e a Free da mesma modelo). Amanhã, quando o Capacity detectar, a linha já aparece como aplicada.', 'r_en' => 'Capacity only creates the exit after the 3 a.m. snapshot. If the page was already deactivated on the website, it shows right away in Page exits › "Deactivated on the website, no exit detected": tick it and see the preview. If it is still active on the website, use "Apply page exit" with the page (and "+ another page" for the VIP and Free of the same model). Tomorrow, when Capacity detects it, the row already shows as applied.'],
        ['p' => 'Apliquei uma saída por engano. Dá para desfazer?', 'p_en' => 'I applied an exit by mistake. Can it be undone?', 'r' => 'Não pelo sistema: o Capacity foi recalculado e os postos refeitos. Fale com o admin; a foto do Capacity antes e depois fica guardada em Saídas aplicadas para comparar.', 'r_en' => 'Not through the system: Capacity was recalculated and posts rebuilt. Talk to the admin; the Capacity snapshot before and after is kept in Exits applied by the system for comparison.'],
        ['p' => 'Como troco alguém de núcleo ou de turno?', 'p_en' => 'How do I move someone to another core or shift?', 'r' => 'Em Colaboradores › Editar, escolha o núcleo e a data. O sistema mostra antes o "de → para" e quantas vagas fixas fecham.', 'r_en' => 'In Employees › Edit, choose the core and the date. The system shows the "from → to" and how many fixed slots close before saving.'],
        ['p' => 'A grade avisou "confira antes de salvar". Posso salvar assim?', 'p_en' => 'The grid said "check before saving". Can I save anyway?', 'r' => 'Pode, marcando "salvar mesmo assim". O aviso existe para folga, indisponibilidade, outro turno, a mesma pessoa em duas páginas, mais de 12 h seguidas ou 52 h na semana.', 'r_en' => 'Yes, by ticking "save anyway". The warning covers days off, unavailability, another shift, the same person on two pages, more than 12 h in a row or 52 h a week.'],
        ['p' => 'Faltam buffers num turno. Como cubro?', 'p_en' => 'A shift is short on buffers. How do I cover it?', 'r' => 'Em Horas extras aparecem os buffers e postos vazios da semana, por bloco de 4 h (T1 a T6). Registre quem se ofereceu e aloque o bloco; o sistema confere 12 h seguidas (quem faz um turno de 8 h pode pegar o bloco vizinho) e 52 h na semana.', 'r_en' => 'Overtime lists the week\'s empty buffers and posts, by 4-hour block (T1 to T6). Record who volunteered and allocate the block; the system checks 12 h in a row (someone on an 8-hour shift can take the neighbouring block) and 52 h a week.'],
        ['p' => 'Para onde vai quem entra pelo Funil?', 'p_en' => 'Where do Intake funnel hires go?', 'r' => 'No Funil de entrada o destino é unidade, turno e núcleo da estrutura nova. Uma página que saiu e ficou ativa de novo no site volta pela seção Ativas no site, fora da escala, no mesmo Funil.', 'r_en' => 'In the Intake funnel the destination is unit, shift and core of the new structure. A page that left and became active on the website again comes back through the Active on the website, outside the schedule section, in the same Funnel.'],
        ['p' => 'Uma página que tinha saído voltou a ficar ativa no site e o sistema não acusou. O que faço?', 'p_en' => 'A page that had left became active on the website again and the system did not flag it. What do I do?', 'r' => 'Abra Funil de entrada › Ativas no site, fora da escala (a detecção vem da DB, não do CRM). Quem saiu pela tela Saídas aparece como "não volta sozinha": em Decidir, escolha a carteira (a de antes vem marcada), a data e, se quiser, o núcleo (OS), e clique em Pôr na escala. O núcleo vale quando a página fica sozinha no posto ou com páginas do mesmo núcleo escolhido. O Capacity é recalculado na hora e os postos entram no próximo Gerar. Página que não é de escala (PH, X, teste) vai para Ignorar.', 'r_en' => 'Open Intake funnel › Active on the website, outside the schedule (detection comes from the DB, not the CRM). A page that left through the Exits screen shows as "does not come back by itself": in Decide, choose the portfolio (the previous one is preselected), the date and, if you want, the core (OS), and click Put in the schedule. The core applies when the page is alone on the position or with pages that have the same chosen core. Capacity is recalculated right away and the positions enter at the next Generate. A page that is not scheduled (PH, X, test) goes to Ignore.'],
        ['p' => 'Onde vejo quantas pessoas faltam e em que unidade?', 'p_en' => 'Where do I see how many people are missing and in which unit?', 'r' => 'Em Quadro e contratação › Capacity: o número grande é a falta de hoje (precisa − tem), o gráfico mostra a evolução por versão e as barras mostram a falta por unidade e turno, com a maior em destaque. Abaixo, a ocupação dos postos na escala da semana, por carteira.', 'r_en' => 'In Headcount & hiring › Capacity: the big number is today\'s shortfall (needs − has), the chart shows the trend per version and the bars show the shortfall per unit and shift, with the largest highlighted. Below, post occupancy in the week\'s schedule, per portfolio.'],
        ['p' => 'Como registro uma requisição de vagas?', 'p_en' => 'How do I record a job requisition?', 'r' => 'Em Quadro e contratação › Requisição de vagas, no Acompanhamento, use "Registrar requisição" na turma (os números vêm da simulação). Quando o recrutamento fechar, "Registrar contratados". Em treinamento e operando vêm sozinhos das Turmas de treinamento. A simulação acima não grava nada.', 'r_en' => 'In Headcount & hiring › Job requisitions, under Tracking, use "Record requisition" on the class (the numbers come from the simulation). When recruitment closes, "Record hires". In training and operating come by themselves from Training classes. The simulation above saves nothing.'],
        ['p' => 'Como o sistema sugere onde o novato entra?', 'p_en' => 'How does the system suggest where a new hire goes?', 'r' => 'Em Turmas de treinamento, cada turma tem "Destino depois do treinamento". A sugestão vai, uma pessoa por vez, para a unidade com mais lacunas no turno na escala da semana em que a turma fica disponível (no empate, a com mais falta no Capacity) e para o núcleo com menos SRs para a parte dele. Confirme ou troque e, na data, use "Cadastrar a partir de…" para criar o cadastro em Colaboradores.', 'r_en' => 'In Training classes, each class has "Destination after training". The suggestion goes, one person at a time, to the unit with the most gaps in the shift in the schedule of the week the class becomes available (on a tie, the one with the largest Capacity shortfall) and to the core with the fewest SRs for its share. Confirm or change it and, on the date, use "Add from…" to create the record in Employees.'],
        ['p' => 'Um New Hire pode ser escalado por engano?', 'p_en' => 'Can a New Hire be scheduled by mistake?', 'r' => 'Não. O motor só escala quem tem cadastro de SR com núcleo, e New Hire não tem. E quem está numa turma de treinamento fica fora da escala normal até o dia disponível para a operação, mesmo que alguém cadastre a pessoa antes. Depois do treinamento, cadastre em Colaboradores com início nesse dia (o botão "Cadastrar a partir de…" em Turmas de treinamento já preenche unidade, núcleo e data).', 'r_en' => 'No. The engine only schedules people with an SR record and a core, and a New Hire has none. And anyone in a training class stays out of the regular schedule until the day they are available for operation, even if someone adds them earlier. After training, add them in Employees starting that day (the "Add from…" button in Training classes fills in unit, core and date).'],
        ['p' => 'Como aviso o RH de quem não trabalha mais para desativar no site?', 'p_en' => 'How do I tell HR who no longer works so they deactivate them on the site?', 'r' => 'Em Quadro e contratação › Fora das unidades, a seção "Para o RH desativar no site" lista quem o RH ainda tem como SR, está fora das unidades e não está trabalhando: saída informada no 5C Escalas, ou afastado / sem escala no site há mais de 30 dias. "Baixar para o RH (.xlsx)" gera a planilha com código, nome completo, admissão, última escala no site e a observação, que diz se a pessoa está de licença ou com indisponibilidade programada. O download é só para WFM, Planejamento e Admin.', 'r_en' => 'In Headcount & hiring › Outside the units, the "For HR to deactivate on the site" section lists people HR still has as SRs who are outside the units and not working: exit recorded in 5C Escalas, or on leave / without a schedule on the site for over 30 days. "Download for HR (.xlsx)" creates the sheet with code, full name, hire date, last schedule on the site and the note, which says whether the person is on leave or has scheduled unavailability. The download is only for WFM, Planning and Admin.'],
        ['p' => 'Como respondo o e-mail do Treinamento a cada ciclo?', 'p_en' => 'How do I reply to the Training e-mail each cycle?', 'r' => 'Em Quadro e contratação › Turmas de treinamento, a tela tem três subseções. Em "E-mail e resposta", cole o e-mail e a lista de contratados do RH e clique em Ler e-mail: o resumo do ciclo mostra cada turma, com status, datas, trainees, páginas e destinos. Em "Páginas", escolha as páginas de uma turma por vez: as escolhidas ficam no topo, a lista abre só nas recomendadas e tem busca; Confirmar leva para a próxima turma sem página. A resposta ao e-mail, de volta em "E-mail e resposta", só libera quando todas as turmas do ciclo têm as páginas confirmadas; aí é só Copiar resposta. O destino de cada novato fica em "Destino dos novatos".', 'r_en' => 'In Headcount & hiring › Training classes, the screen has three subsections. In "E-mail and reply", paste the e-mail and the HR hire list and click Read e-mail: the cycle summary shows each class with status, dates, trainees, pages and destinations. In "Pages", pick the pages one class at a time: the picked ones stay on top, the list opens with only the recommended ones and has a search; Confirm takes you to the next class without pages. The reply to the e-mail, back in "E-mail and reply", only unlocks when every class in the cycle has its pages confirmed; then just Copy reply. Each new hire\'s destination is in "New hire destination".'],
        ['p' => 'Por que um SR com ótimo desempenho aparece no nível 0 ou 1?', 'p_en' => 'Why does an SR with great performance show at level 0 or 1?', 'r' => 'Quase sempre pela Integrity (faltas ou quebra de P&G) ou pelo SLA (Process): o score multiplica os três, então um deles baixo puxa o resto. A conta semana a semana aparece clicando no nome em Análise › KPI dos SRs.', 'r_en' => 'Almost always because of Integrity (absences or P&G breaches) or SLA (Process): the score multiplies the three, so one low factor pulls the rest down. The week-by-week calculation shows when you click the name in Analysis › SR KPI.'],
        ['p' => 'As faltas de um SR parecem altas demais. Está contando a escala dobrada?', 'p_en' => 'An SR\'s absences look too high. Is it counting double scheduling?', 'r' => 'Não deveria. A falha administrativa (escala dobrada ou fora do horário) e o bloco em que o SR estava presente ficam fora da conta: só conta o dia com falta que sobra na classificação oficial (abs_adh_af). Se a tela do KPI avisar que ela não pode ser lida, as faltas ficam de fora da Integrity. Depois de uma atualização, use "Recalcular agora" no KPI dos SRs para não esperar o cache.', 'r_en' => 'It should not. Administrative failure (double scheduling or outside the shift) and blocks where the SR was present are left out: only the days absent left in the official classification (abs_adh_af) count. If the KPI screen warns that it cannot be read, absences stay out of Integrity. After an update, use "Recalculate now" on SR KPI so you do not wait for the cache.'],
        ['p' => 'Por que não vejo o KPI de cada SR?', 'p_en' => 'Why can\'t I see each SR\'s KPI?', 'r' => 'O score, o nível, as faltas e o P&G de cada SR aparecem só para os perfis WFM, Planejamento e Admin.', 'r_en' => 'Each SR\'s score, level, absences and P&G are visible only to the WFM, Planning and Admin profiles.'],
        ['p' => 'Perdi o que digitei quando deu erro?', 'p_en' => 'Did I lose what I typed when an error happened?', 'r' => 'Não. A tela volta com o formulário preenchido e a mensagem de erro em cima dele.', 'r_en' => 'No. The screen comes back with the form filled in and the error message above it.'],
        ['p' => 'Apareceu um código de ocorrência. O que é?', 'p_en' => 'An incident code appeared. What is it?', 'r' => 'Um erro inesperado. Tente de novo; se repetir, passe o código para o admin, que acha o detalhe no log.', 'r_en' => 'An unexpected error. Try again; if it happens again, give the code to the admin, who finds the details in the log.'],
        ['p' => 'Como troco o tema ou o idioma?', 'p_en' => 'How do I change the theme or language?', 'r' => 'No topo do menu: Claro, Escuro ou Automático (segue o sistema) e PT ou EN. A escolha fica salva neste navegador.', 'r_en' => 'At the top of the menu: Light, Dark or Automatic (follows the system) and PT or EN. The choice is saved in this browser.'],
        ['p' => 'Posso usar no celular?', 'p_en' => 'Can I use it on my phone?', 'r' => 'Sim. O menu abre pelo botão "Menu" e as tabelas viram cartões. A grade da escala continua com rolagem para o lado.', 'r_en' => 'Yes. The menu opens with the "Menu" button and tables turn into cards. The schedule grid keeps side scrolling.'],
        ['p' => 'Como pratico sem mexer na escala real?', 'p_en' => 'How do I practice without touching the real schedule?', 'r' => 'Ligue o Modo Treino em Ajuda › Tutorial. Aparece uma faixa em todas as telas; "Recomeçar o treino" volta tudo ao começo e "Sair do treino" volta para o sistema real. No treino a saída de página não mexe no Capacity e os arquivos baixados levam TREINO_ no nome: não poste esses arquivos no site da 5C.', 'r_en' => 'Turn on Training mode in Help › Tutorial. A banner shows on every screen; "Restart training" resets everything and "Leave training" goes back to the real system. In training a page exit does not touch Capacity and downloaded files carry TREINO_ in the name: do not post those files on the 5C website.'],
        ['p' => 'Por que o sistema sugeriu tirar uma página da minha unidade?', 'p_en' => 'Why did the system suggest taking a page out of my unit?', 'r' => 'A página ficou abaixo de 85% da meta 5CReps na unidade e o prazo da política venceu (quanto pior o atingimento, menor o prazo). A sugestão aparece em Páginas › Owners e backups, com prévia; nada muda sem confirmação. As regras completas ficam em Ajuda › Regras.', 'r_en' => 'The page stayed below 85% of the 5CReps target in the unit and the policy deadline was missed (the worse the attainment, the shorter the deadline). The suggestion shows up in Pages › Owners and backups, with a preview; nothing changes without confirmation. The full rules are in Help › Rules.'],
        ['p' => 'Como troco um OC, um OS ou um OA?', 'p_en' => 'How do I change an OC, an OS or an OA?', 'r' => 'Em Pessoas › Roster da liderança, "Trocar" no cargo: escolha quem entra, o que acontece com quem sai (fica com o lugar de quem entrou, vira SR no mesmo núcleo ou fica sem núcleo) e a data. OA: "Incluir OA", "Mudar semana" ou "Tirar". Depois, recalcule as semanas a partir da data.', 'r_en' => 'In People › Leadership roster, "Change" on the role: choose who comes in, what happens to the person leaving (takes the newcomer\'s place, becomes an SR in the same core or is left without a core) and the date. OA: "Add OA", "Change week" or "Remove". Then recalculate the weeks from that date.'],
        ['p' => 'Um SR quer trabalhar como assistente ou mudar de turno. Como faço?', 'p_en' => 'An SR wants to work as an assistant or change shift. What do I do?', 'r' => 'O líder registra em Pessoas › Solicitações. O Planejamento aprova e, em "Aprovadas", escolhe com quem trocar (primeiro aparece quem pediu o contrário) e a data. Depois, recalcule as semanas a partir dessa data.', 'r_en' => 'The leader records it in People › Requests. Planning approves it and, under "Approved", picks whom to swap with (those who asked for the opposite come first) and the date. Then recalculate the weeks from that date.'],
        ['p' => 'Como baixo o organograma, a escala da liderança ou a escala das páginas em PDF?', 'p_en' => 'How do I download the org chart, the leadership schedule or the pages schedule as a PDF?', 'r' => 'Escala das páginas: na Grade, "Baixar PDF das páginas" (uma folha por página) ou "PDF" na linha da página. Histórico de meta de quem está escalado em cada página: na Grade, "Baixar PDF das metas" ou "Metas" na linha da página (atingimento de cada pessoa na página nas 4 semanas anteriores). Organograma e escala da liderança: nas duas telas, "Baixar PDF" e, na impressão, "Salvar como PDF" (o nome do arquivo já vem com a data). Organograma: sai como está na tela, em 1 folha A3 em pé, com a data da estrutura; com os núcleos recolhidos sai só a liderança, abra os núcleos para incluir os SRs. Escala da liderança: A4 paisagem com o papel timbrado, um turno por folha e os OMs no fim, sem as marcas de conferência.', 'r_en' => 'Pages schedule: in the Grid, "Download pages PDF" (one sheet per page) or "PDF" on the page row. Goal history of the people scheduled on each page: in the Grid, "Download goals PDF" or "Goals" on the page row (each person\'s attainment on the page over the previous 4 weeks). Org chart and leadership schedule: on both screens, "Download PDF" and then "Save as PDF" when printing (the file name already has the date). Org chart: as shown on screen, on one portrait A3 sheet, with the structure date; with the cores collapsed only the leadership prints, open the cores to include the SRs. Leadership schedule: A4 landscape on letterhead, one shift per sheet and the OMs at the end, without the check marks.'],
        ['p' => 'Como faço um casal folgar junto?', 'p_en' => 'How do I give a couple the same days off?', 'r' => 'Em Pessoas › Folga juntos, associe as duas pessoas. A tabela mostra as folgas dos próximos 21 dias de cada uma. Se não coincidirem, aplique um dos ajustes sugeridos a partir de uma data: o SR muda para o núcleo de mesmo ciclo do par (mesma unidade e turno), o OC ou OA troca o ciclo com um colega do turno, ou o OS troca de núcleo com outro OS. Depois recalcule as semanas a partir da data (Recalcular com o mínimo de mudanças). O motor dá aos dois o mesmo dia de Overlap. OA com semana fixa se ajusta no Roster da liderança.', 'r_en' => 'In People › Days off together, link the two people. The table shows each person\'s days off for the next 21 days. If they do not match, apply one of the suggested adjustments from a date: the SR moves to the core with the pair\'s cycle (same unit and shift), the OC or OA swaps cycles with a colleague on the shift, or the OS swaps cores with another OS. Then recalculate the weeks from that date (Recalc With Minimum Changes). The engine gives both the same Overlap day. An OA with a fixed week is adjusted in the Leadership roster.'],
        ['p' => 'Como equilibro o faturamento entre as unidades?', 'p_en' => 'How do I balance revenue across units?', 'r' => 'Em Páginas › Equilíbrio das unidades. A meta é o mesmo faturamento total em cada unidade e coordenador. A tabela mostra o faturamento de 30 dias de cada unidade e turno e o desvio contra a média do turno (até ±5% está equilibrado), e ao lado o por SR, para acompanhar. Abaixo vêm as trocas de unidade sugeridas, da que mais ajuda para a que menos; as páginas da mesma modelo trocam juntas e só depois de 28 dias na unidade. "Aplicar…" recalcula o Capacity e gera as semanas com o mínimo de mudanças. O gap que sobrar, o Funil cobre: unidade abaixo da média ganha nota.', 'r_en' => 'In Pages › Unit balance. The goal is the same total revenue in each unit and coordinator. The table shows the 30-day revenue of each unit and shift and the gap against the shift average (within ±5% is balanced), with the per-SR figure next to it for follow-up. Below are the suggested unit moves, from the most helpful to the least; pages of the same model move together and only after 28 days in the unit. "Apply…" recalculates Capacity and generates the weeks with minimum changes. Any remaining gap is covered by the Funnel: a unit below average gets a higher score.'],
        ['p' => 'Como os OS dividem as páginas?', 'p_en' => 'How do the OSs split the pages?', 'r' => 'Pelo faturamento de 30 dias dos postos em cada unidade e turno: o OS1 fica com as maiores páginas, o OS3 com as menores e o OS2 com um misto (na parte de cima, OS1, OS1, OS2; na de baixo, OS2, OS3, OS3; o corte fica onde o OS3 soma de 15% a 20% do faturamento). O OS2 cobre os postos do OS1 e do OS3; nos postos do OS2, os grandes ficam com o OS1 e os pequenos com o OS3. Os melhores SRs (nível do KPI, depois o score) vão para o OS1; no OS2, quem conhece páginas grandes e pequenas. Em Páginas › Equilíbrio das unidades, abra a unidade e o turno, confira a proposta e "Aplicar divisão" a partir de uma data; depois gere as semanas com o mínimo de mudanças.', 'r_en' => 'By the posts\' 30-day revenue in each unit and shift: OS1 gets the biggest pages, OS3 the smallest and OS2 a mix (top part OS1, OS1, OS2; bottom part OS2, OS3, OS3; the cut is where OS3 adds up to 15% to 20% of the revenue). OS2 covers the OS1 and OS3 posts; on OS2 posts, the big ones are covered by OS1 and the small ones by OS3. The best SRs (KPI level, then score) go to OS1; OS2 gets those who know both big and small pages. In Pages › Unit balance, open the unit and shift, check the proposal and "Apply split" from a date; then generate the weeks with minimum changes.'],
        ['p' => 'Por que uma página não troca de unidade, ou aparece em "Páginas sem quem as conheça"?', 'p_en' => 'Why does a page not move unit, or show up in "Pages nobody in the unit knows"?', 'r' => 'Conhecer a página pesa no planejamento: conhece quem tem 3 dias ou mais nela nas últimas 8 semanas (v4_conhece_dias). O Equilíbrio só sugere levar uma modelo para a unidade que tem pelo menos 2 SRs que a conhecem (v4_conhece_min) e lista as páginas abaixo disso na própria unidade, com quem as conhece em outra. Como o Gerar escolhe só entre os SRs da unidade e do turno, a correção é mudar a pessoa de unidade no mesmo turno e nível, com uma compensação no sentido contrário.', 'r_en' => 'Knowing the page weighs in planning: an SR knows a page after 3 days or more on it in the last 8 weeks (v4_conhece_dias). Unit balance only suggests moving a model to a unit with at least 2 SRs who know it (v4_conhece_min) and lists the pages below that in their own unit, with who knows them elsewhere. Since Generate only picks among the SRs of the unit and shift, the fix is to move the person to that unit in the same shift and level, with a compensating move the other way.'],
        ['p' => 'O Comercial cadastrou uma página nova. Como ela entra na escala?', 'p_en' => 'Sales added a new page. How does it get into the schedule?', 'r' => 'Sozinha: no próximo Gerar ou Recalcular, página ativa no site cadastrada há até 7 dias entra no Capacity (na carteira da mesma modelo ou no destino do Funil, com o volume do arquétipo do tier) e ganha postos. Até completar 28 dias, entra na fila da escala com o faturamento do arquétipo do tier (a mediana das páginas do mesmo tier). Depois, é só publicar e postar os CSVs dela.', 'r_en' => 'On its own: at the next Generate or Recalculate, an active page added on the website up to 7 days ago joins Capacity (in the portfolio of the same model or at the Funnel destination, with the tier archetype volume) and gets posts. Until it completes 28 days, it enters the schedule queue with the tier archetype revenue (the median of the pages of the same tier). Then just publish and post its CSVs.'],
        ['p' => 'O OM pediu que fulano só faça X (uma página, só assistente, só estas páginas, fora de uma página). Onde vejo e mando?', 'p_en' => 'The OM asked that someone only does X (one page, assistant only, these pages only, banned from a page). Where do I see it and send it?', 'r' => 'Em Páginas › Restrições dos OM. A tela lê do banco na hora as regras de cada página (alocação, equipe fixa com main e cover, quem é de outra unidade, só assistente, proibidos, divisões) e de cada pessoa (uma página, várias páginas, só estas páginas, baixo fluxo, não subordinado, inegociáveis e outras). "Baixar PDF" gera o documento por unidade (U1, U2, U3), no papel timbrado, para mandar às equipes. Para uma página só, use o botão PDF dela em Páginas › Configuração das páginas. Pedido novo do OM: mande ao Planejamento, que registra; vale a partir do próximo Gerar. Para tirar ou mudar uma restrição, use o painel Gerenciar as restrições, abaixo do documento: Desativar guarda a restrição para ativar de novo; Apagar tira de vez.', 'r_en' => 'In Pages › OM restrictions. The screen reads live from the database each page\'s rules (allocation, fixed team with main and cover, who is from another unit, assistant only, banned, splits) and each person\'s (one page, several pages, these pages only, low flow, not a subordinate, non-negotiables and others). "Download PDF" makes the document per unit (U1, U2, U3), on letterhead, to send to the teams. For a single page, use its PDF button in Pages › Page settings. New OM request: send it to Planning, who records it; it applies from the next Generate. To remove or change a restriction, use the Manage restrictions panel below the document: Deactivate keeps it to activate again; Delete removes it for good.'],
        ['p' => 'Por que fulano saiu da equipe fixa sozinho?', 'p_en' => 'Why did someone leave the fixed team by themselves?', 'r' => 'Porque foi desligado ou a página saiu. Desde a 1.19.16 as restrições de quem sai e de página que sai fecham sozinhas no último dia: a pessoa sai da equipe fixa (o resto da equipe fica), e fecham o só assistente, o proibido e a divisão. Isso roda no fim da saída de página e antes de cada Gerar, e fica no log. Quem só passou para a liderança (OS, OC, OM, OA) não perde nada por isso. Se a pessoa não saiu, confira o cadastro em Colaboradores.', 'r_en' => 'Because they were let go or the page left. Since 1.19.16 the restrictions of whoever leaves and of a page that leaves close by themselves on the last day: the person leaves the fixed team (the rest of the team stays), and assistant only, banned and split close. This runs at the end of a page exit and before each Generate, and is logged. Someone who only moved to leadership (OS, OC, OM, OA) loses nothing because of it. If the person did not leave, check their record in Employees.'],
        ['p' => 'Por que o SR da Privacy ou da Fanvue não cobre OnlyFans no mesmo turno?', 'p_en' => 'Why doesn\'t the Privacy or Fanvue SR cover OnlyFans in the same shift?', 'r' => 'Pela regra "uma plataforma por turno" (1.19.15): quem faz Privacy, Fanvue ou PlayBoy não acumula nem cobre página de outra plataforma no mesmo turno, e o contrário também vale. A lacuna do OnlyFans vai para outro SR do turno. No Recalcular com o mínimo de mudanças, a mistura que estava na versão publicada sai: fica a página da Privacy, Fanvue ou PlayBoy. A plataforma de cada página muda em Páginas › Configuração das páginas.', 'r_en' => 'Because of the "one platform per shift" rule (1.19.15): whoever works Privacy, Fanvue or PlayBoy does not stack or cover a page of another platform in the same shift, and the reverse also holds. The OnlyFans gap goes to another SR on the shift. In Recalc With Minimum Changes, a mix that was in the published version is removed: the Privacy, Fanvue or PlayBoy page stays. Each page\'s platform is changed in Pages › Page settings.'],
        ['p' => 'O que é o vN no cabeçalho do PDF?', 'p_en' => 'What is the vN in the PDF header?', 'r' => 'É a versão do documento. Organograma, escala da liderança, KPI, regras, owners e restrições dos OM levam "versão vN" no cabeçalho e no nome do arquivo. O número só sobe quando o conteúdo impresso muda; imprimir de novo o mesmo conteúdo mantém o número. Assim dá para saber se a equipe está com o documento mais novo. A escala das páginas usa a versão do plano (ex.: v32.1).', 'r_en' => 'It is the document version. Org chart, leadership schedule, KPI, rules, owners and OM restrictions carry "version vN" in the header and in the file name. The number only goes up when the printed content changes; printing the same content again keeps the number. That way you know whether the team has the newest document. The pages schedule uses the plan version (e.g. v32.1).'],
        ['p' => 'Mudou algo no meio da semana. Como recalculo só daqui para frente?', 'p_en' => 'Something changed mid-week. How do I recalculate only from now on?', 'r' => 'Em Gerar escala, escolha o "A partir de" (dia e turno) e deixe marcada "Antes do corte, igual ao site": antes do corte as células vêm da escala oficial do site, como estão. Depois de publicar, use na Grade o "CSV a partir de" no mesmo corte: o CSV e os PDFs saem só dali em diante, e no dia do corte os blocos de antes dele vão iguais ao site. Ao salvar uma mudança de núcleo, turno ou nível, Colaboradores já leva ao Gerar com o "a partir de" marcado.', 'r_en' => 'In Generate schedule, pick "From" (day and shift) and keep "Before the cut-off, same as the website" ticked: before the cut-off the cells come from the official schedule on the website, as they are. After publishing, use "CSV from" on the Grid with the same cut-off: the CSV and the PDFs only cover from there on, and on the cut-off day the blocks before it go out the same as the website. When you save a core, shift or level change, Employees already takes you to Generate with "From" set.'],
        ['p' => 'O que muda em cada versão?', 'p_en' => 'What changes in each version?', 'r' => 'Veja o Changelog (link no rodapé). Mudanças instaladas e ainda não publicadas aparecem primeiro, como "não publicada".', 'r_en' => 'See the Changelog (link in the footer). Changes installed but not yet published appear first, marked "unpublished".'],
        ['p' => 'Histórico (1.13.5, 31/10): apliquei uma saída e outra página da mesma dupla ficou com lacuna. Por quê?', 'p_en' => 'History (1.13.5, 10/31): I applied an exit and another page of the same pair got a gap. Why?', 'r' => 'Até a 1.13.4, o posto refeito sem a página que saiu ficava aberto mesmo quando o original valia só em 31/10, e passava a valer junto com o posto do Capacity: dois postos para a mesma página e turno, gente dividida entre eles e lacuna (foi o caso da Thalia 147m). Desde a 1.13.5 a cópia vale no mesmo período do original. Os postos que já tinham duplicado são corrigidos pelo script ES_39; depois, recalcule as semanas.', 'r_en' => 'Up to 1.13.4, the post rebuilt without the page that left stayed open even when the original was only valid on 10/31, and became valid together with the Capacity post: two posts for the same page and shift, people split between them and gaps (that was the case of Thalia 147m). Since 1.13.5 the copy has the same period as the original. Posts already duplicated are fixed by script ES_39; then recalculate the weeks.'],
        ['p' => 'Histórico (31/10): como postei a semana da virada (31/10)?', 'p_en' => 'History (10/31): how did I post the switch-over week (10/31)?', 'r' => 'Antes de 31/10 às 21:00 vale a escala já postada: não apague nem poste nada antes disso. Na Grade › Postar no site da 5C, o roteiro dessa semana manda Delete Range só de 01/11, apagar à mão em 31/10 só o T6 e postar com Date Schedule 31/10; o CSV traz só os blocos a partir da virada.', 'r_en' => 'Before 10/31 at 21:00 the schedule already posted applies: do not delete or post anything before that. In Grid › Post on the 5C website, that week\'s steps say Delete Range only from 11/01, delete by hand on 10/31 only T6 and post with Date Schedule 10/31; the CSV only has the blocks from the switch-over.'],
        ['p' => 'Histórico (31/10): a tela Configuração dos times sumiu do menu principal.', 'p_en' => 'History (10/31): the Team setup screen left the main menu.', 'r' => 'Ela é da estrutura antiga e fica no grupo Legado. Depois da virada de 31/10 21:00 é só consulta; a estrutura nova fica em Colaboradores e no Organograma.', 'r_en' => 'It belongs to the old structure and is in the Legacy group. After the Oct 31 21:00 switch-over it is read-only; the new structure is in Employees and the Org chart.'],
    ];
}

// Passos do tour (a tela Trocas de página saiu: está no menu Legado, só admin): tela, elemento a destacar (seletor CSS; sem ele o cartão aparece sozinho),
// texto e as ações da etapa na plataforma e no site da 5C. A ordem é a da semana: primeiro o
// que muda a entrada da escala (cadastro, pedidos, solicitações, saídas, treinamento), depois
// gerar, conferir e ajustar, publicar e postar.
function escTourPassos(): array {
    $passos = [
        ['tela' => 'painel', 'alvo' => '.kpis', 'titulo' => 'Painel', 'titulo_en' => 'Dashboard',
         'texto' => 'Começa aqui: os cartões mostram o que está pendente (pedidos, solicitações, saídas de página) e a escala das duas semanas. Resolva os pendentes antes de gerar; clique num cartão para ir direto.', 'texto_en' => 'Start here: the cards show what is pending (requests, SR requests, page exits) and the schedule for the two weeks. Sort out the pending items before generating; click a card to go straight there.',
         'plataforma' => ['Olhar os cartões em laranja primeiro'], 'plataforma_en' => ['Look at the orange cards first'], 'site' => [], 'site_en' => []],
        ['tela' => 'gerar', 'alvo' => '.acoes', 'titulo' => 'Gerar escala', 'titulo_en' => 'Generate schedule',
         'texto' => 'Escolha a semana. Sem versão, "Gerar rascunho". Com versão já postada, use "Recalcular com o mínimo de mudanças" (só mexe no necessário); "Recalcular tudo" refaz a semana e mantém os ajustes travados. Mudou algo no meio da semana: escolha o "A partir de" (dia e turno) e deixe marcada "Antes do corte, igual ao site". Ao clicar, uma tela de progresso mostra as três etapas (Verificação, Capacity e Escala) e trava o resto do sistema até terminar: o sistema confere as pendências (saída de página a conferir leva às Saídas), recalcula o Capacity, inclui páginas ativas que faltavam, completa as vagas sem equipe e fecha as restrições de quem saiu; a mensagem depois diz o que mudou. "Verificar mudanças" confere se o Capacity, os pedidos ou o cadastro mudaram.', 'texto_en' => 'Pick the week. With no version, "Generate draft". With a version already posted, use "Recalc With Minimum Changes" (only touches what is needed); "Recalculate everything" redoes the week and keeps locked adjustments. Something changed mid-week: pick "From" (day and shift) and keep "Before the cut-off, same as the website" ticked. Before generating, the system recalculates Capacity, adds missing active pages, fills slots with no team and closes the restrictions of whoever left; the message afterwards says what changed. "Check for changes" sees whether Capacity, requests or records changed.',
         'plataforma' => ['Gerar ou recalcular o rascunho da semana'], 'plataforma_en' => ['Generate or recalculate the week\'s draft'], 'site' => [], 'site_en' => []],
        ['tela' => 'grade', 'alvo' => 'table.grade', 'titulo' => 'Grade da escala', 'titulo_en' => 'Schedule grid',
         'texto' => 'Cada linha é uma página; cada coluna, um dia do turno escolhido. Laranja é lacuna. Clique numa célula para ver o porquê e ajustar: o ajuste fica travado nos recálculos.', 'texto_en' => 'Each row is a page; each column a day of the chosen shift. Orange is a gap. Click a cell to see why and adjust it: the adjustment stays locked on recalculations.',
         'plataforma' => ['Conferir lacunas e anomalias', 'Ajustar células quando precisar'], 'plataforma_en' => ['Check gaps and anomalies', 'Adjust cells when needed'], 'site' => [], 'site_en' => []],
        ['tela' => 'grade', 'alvo' => '.kpis', 'titulo' => 'Publicar', 'titulo_en' => 'Publish',
         'texto' => '"Publicar esta versão" mostra antes o resumo (lacunas, anomalias, postos sem ninguém). Com anomalia, marque "estou ciente". A versão publicada antes vira substituída.', 'texto_en' => '"Publish this version" shows a summary first (gaps, anomalies, empty posts). With anomalies, tick "I am aware". The previously published version becomes superseded.',
         'plataforma' => ['Publicar a versão da semana'], 'plataforma_en' => ['Publish the week\'s version'], 'site' => [], 'site_en' => []],
        ['tela' => 'grade', 'alvo' => '#postar', 'titulo' => 'Postar no site da 5C', 'titulo_en' => 'Post on the 5C website',
         'texto' => 'Depois de publicar, cada página tem um cartão com o CSV. Siga o roteiro e marque cada passo; "Sem mudança" mostra o que pode ficar como está.', 'texto_en' => 'After publishing, each page has a card with the CSV. Follow the steps and mark each one; "No change" shows what can stay as it is.',
         'plataforma' => ['Marcar "1 · Apaguei" e "2 · Postei" em cada página'], 'plataforma_en' => ['Mark "1 · Deleted" and "2 · Posted" on each page'],
         'site' => ['Delete Range das páginas que já têm escala na semana', 'Save Schedule CSV: Model = página, Date Schedule e Date End da semana', 'Colar o CSV e salvar'], 'site_en' => ['Delete Range on pages that already have a schedule that week', 'Save Schedule CSV: Model = page, Date Schedule and Date End of the week', 'Paste the CSV and save']],
        ['tela' => 'lideranca', 'alvo' => '.kpis', 'titulo' => 'Escala da liderança', 'titulo_en' => 'Leadership schedule',
